'use client';

import * as React from 'react';
import { motion, type Variants } from 'motion/react';

import {
  getVariants,
  useAnimateIconContext,
  IconWrapper,
  type IconProps,
} from '@animate-ui/react/icons';

type UngroupProps = IconProps<keyof typeof animations>;

const animations = {
  default: {
    lower: {
      initial: { x: 0, y: 0 },
      animate: {
        x: [0, 1.5, 0],
        y: [0, 1.5, 0],
        transition: { duration: 0.9, times: [0, 0.45, 1], ease: 'easeInOut' },
      },
    },
    upper: {
      initial: { x: 0, y: 0 },
      animate: {
        x: [0, -1.5, 0],
        y: [0, -1.5, 0],
        transition: { duration: 0.9, times: [0, 0.45, 1], ease: 'easeInOut' },
      },
    },
  } satisfies Record<string, Variants>,
} as const;

function IconComponent({ size, ...props }: UngroupProps) {
  const { controls } = useAnimateIconContext();
  const variants = getVariants(animations);

  return (
    <motion.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      {...props}
    >
      <motion.rect
        x="11"
        y="14"
        width="10"
        height="7"
        rx="2"
        variants={variants.lower}
        initial="initial"
        animate={controls}
      />
      <motion.rect
        x="3"
        y="3"
        width="10"
        height="7"
        rx="2"
        variants={variants.upper}
        initial="initial"
        animate={controls}
      />
    </motion.svg>
  );
}

function Ungroup(props: UngroupProps) {
  return <IconWrapper icon={IconComponent} {...props} />;
}

export {
  animations,
  Ungroup,
  Ungroup as UngroupIcon,
  type UngroupProps,
  type UngroupProps as UngroupIconProps,
};
